        "source_handle": "P0096",
        "field_path": [
          "study_summary_A",
          "research_scope"
        ],
        "value": "非小细胞肺癌（NSCLC）患者，聚焦于肠道微生物组、肺部微生物组及其代谢产物与免疫检查点抑制剂（ICI）疗效及毒性的关系。",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::9577f4b99b0d1e6b2a5a3adc",
          "snapshot::769a855a4ccae40446adf28a",
