      {
        "atom_id": "atom::d2a6333196eb31e51bfc64a4",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "approach"
        ],
        "value": "采用多中心回顾性队列研究设计。纳入标准：确诊为NSCLC且接受ICI单药治疗的患者。暴露变量：在ICI治疗开始前2个月至开始后1个月内是否使用抗生素。主要结局指标：无进展生存期（PFS）和总生存期（OS）。统计分析方法：使用Kaplan-Meier法绘制生存曲线并进行Log-rank检验，使用Cox比例风险回归模型进行多变量分析以调整混杂因素。亚组分析：根据PD-L1表达水平（<50% vs ≥50%）将患者分为两组，分别评估抗生素使用对各亚组生存预后的影响。",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
      },
      {
        "atom_id": "atom::51ccf9f282e40e4e28b544a2",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "contribution_and_limits"
        ],
        "value": {
          "contribution": "提供了在NSCLC特定人群中，抗生素使用对ICI疗效影响的临床证据，特别是揭示了PD-L1表达水平作为潜在效应修饰因子的重要性。",
          "limits": "所给摘要未交代具体的多变量分析中调整了哪些协变量；未提供PD-L1检测的具体平台或阈值判定细节；样本量虽大但为回顾性研究，可能存在选择偏倚和混杂因素；仅关注ICI单药治疗，未涵盖联合治疗方案；结果仅在NSCLC背景下成立，外推至其他癌种需谨慎。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
      },
      {
        "atom_id": "atom::ad1720dc1737d5dd196bcf87",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "key_findings"
        ],
        "value": {
          "conditions": "整体NSCLC人群 (N=531)",
          "finding": "抗生素使用与较短的中位OS显著相关（11.7个月 vs 16.1个月, p=0.028），但与PFS无显著关联（3.5个月 vs 3.5个月, p=0.287）。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
      },
      {
        "atom_id": "atom::1b9a2a07689df46a86ac600c",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "key_findings"
        ],
        "value": {
          "conditions": "PD-L1表达 <50% 的亚组 (N=部分, 具体人数未明确给出但包含在265名有PD-L1数据的患者中)",
          "finding": "抗生素使用与未使用者相比，中位PFS（3.3 vs 2.8个月, p=0.88）和中位OS（9.5 vs 17.1个月, p=0.24）均无显著差异。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
      },
      {
        "atom_id": "atom::a45c49dc91d86e47439985d6",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "key_findings"
        ],
        "value": {
          "conditions": "PD-L1表达 ≥50% 的亚组 (N=部分, 具体人数未明确给出但包含在265名有PD-L1数据的患者中)",
          "finding": "抗生素使用者显示出显著更短的中位PFS（4.2 vs 9.4个月, p=0.012）和中位OS（11.9 vs 28.4个月, p=0.011）。该亚组中抗生素的负面影响比整体人群更为显著。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
      },
      {
        "atom_id": "atom::1171c861e1375a2547437d59",
        "source_handle": "P0517",
        "field_path": [
          "study_summary_A",
          "paper_kind"
        ],
        "value": "empirical",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
